            return try await GraphQLPost.send(
                to: endpoint,
                body: try JSONEncoder().encode(payload),
                headers: headers,
                transport: transport
            )
        } catch let MFETransportError.network(message, status) {
            throw BFFError.network(message, status: status)
        }
    }
